bulkActions.modalInitCode:
const casesWithDifferentTransition = selectedRows.filter(
  c => c?.transicion_id !== selectedRows[0]?.transicion_id
);

if (casesWithDifferentTransition.length > 0) {
  const expedientes = casesWithDifferentTransition
    .map(c => c?.expediente ?? c?.id ?? '')
    .filter(Boolean);
  Swal.fire({
    icon: "error",
    title: "Error",
    text: `Los casos con expediente (${expedientes.join(", ")}) no tienen el mismo estado; solo puedes cambiar estado a casos con el mismo estado.`,
  });
  return { abort: true };
}

return apiService.get(
  `/case-available-states/${selectedRows[0].id}`
).then(data=>{
  const items = data?.data?.data?.items || []
  if (items.length > 0) {
    const stateOptions = items.map(state => ({
      label: state.estado_siguiente.nombre,
      value: state.transition.id,
    }))

    return {
      selectOptions: {
        state: stateOptions,
      },
    };
  }
});

