modalFields.showWhen:
if (loadPass) {
  return (async () => {
    const fechaActual = new Date();
    const lastConectionTime = new Date(fechaActual.getTime() - 5 * 60 * 1000);
    const zonaHoraria = 'America/Bogota';
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone: zonaHoraria,
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit',
      hour12: false
    }).formatToParts(lastConectionTime);
    const d = Object.fromEntries(parts.map(p => [p.type, p.value]));
    const ms = lastConectionTime.getMilliseconds().toString().padStart(3, '0');
    const offsetMinutes = lastConectionTime.getTimezoneOffset();
    const absOffset = Math.abs(offsetMinutes);
    const sign = offsetMinutes <= 0 ? '+' : '-';
    const offsetHours = Math.floor(absOffset / 60).toString().padStart(2, '0');
    const offsetMins = (absOffset % 60).toString().padStart(2, '0');
    const timezoneStr = `${sign}${offsetHours}${offsetMins}`;
    const fechaFormateada = `${d.year}-${d.month}-${d.day} ${d.hour}:${d.minute}:${d.second}.${ms} ${timezoneStr}`;
    const searchTerm = (kaceRemoteSearchTerm ?? '').trim();
    const filters = [
      {
        filters: [
          { field: 'last_seen_at', operator: 'gte', type: 'OR', value: fechaFormateada },
          { field: 'nombres', operator: 'ilike', type: 'OR', value: 'gestor' }
        ],
        groupType: 'AND'
      },
      { field: 'deleted_at', operator: 'null', type: 'AND', value: 'null' }
    ];
    if (searchTerm) {
      filters.push({
        filters: [
          { field: 'nombres', operator: 'ilike', type: 'OR', value: searchTerm },
          { field: 'apellido1', operator: 'ilike', type: 'OR', value: searchTerm },
          { field: 'apellido2', operator: 'ilike', type: 'OR', value: searchTerm }
        ],
        groupType: 'AND'
      });
    }
    const response = await apiService.post('/users/search', {
      filter: filters,
      limit: kaceSelectPageSize,
      offset: (kaceSelectPage - 1) * kaceSelectPageSize,
      order: { direction: 'asc', field: 'nombres' },
      relationship: null
    });
    const users = response?.data?.data?.items ?? [];
    const mappedUsers = users.map((user) => ({
      label: `${user.nombres ?? ''} ${user.apellido1 ?? ''} ${user.apellido2 ?? ''}`.replace(/\s+/g, ' ').trim(),
      value: user.id
    }));
    const pageItems = kaceSelectPage === 1
      ? [{ label: 'Seleccionar usuario', value: '' }, ...mappedUsers]
      : mappedUsers;
    setSelectOptions('user', pageItems, { append: kaceSelectPage > 1 });
    return true;
  })();
}

